import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
I=G['Demo pair 1 input']; O=G['Demo pair 1 output']
for i,row in enumerate(I):
    for j,v in enumerate(row):
        if v!=4: print('in',i,j,v)
for i,row in enumerate(O):
    for j,v in enumerate(row):
        if v!=4: print('out',i,j,v)

def f(g):
    from collections import Counter
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    seen={bg}
    vals={}
    for i,r_ in enumerate(g):
        for j,v in enumerate(r_):
            if v not in seen: seen.add(v); vals[v]=[]
            vals[v].append((i,j))
    block_v=max(vals,key=lambda v:len(vals[v]))
    pts=vals[block_v]
    mr=(min(i for i,_ in pts)+max(i for i,_ in pts))/2
    mc=(min(j for _,j in pts)+max(j for _,j in pts))/2
    out=[r[:] for r in g]
    for v,ps in vals.items():
        if v==block_v: continue
        for i,j in ps:
            for ai,bj in [(i,j),(int(round(2*mr-i)),j),(i,int(round(2*mc-j))),(int(round(2*mr-i)),int(round(2*mc-j)))]:
                if 0<=ai<len(out) and 0<=bj<len(out[0]): out[ai][bj]=v
    return out
r=f(G['Demo pair 1 input'])
print(json.dumps(r)==json.dumps(O))
T=G['Test input']
res=f(T)
for row in res: print(''.join(map(str,row)))

